class TestDiagramEngineConcurrency:
    """Thread-safety and concurrent access."""

    def test_concurrent_generation(self, engine):
        """Multiple threads should generate without corruption."""
        # Arrange
        import threading
        spec = {"type": "flowchart", "nodes": ["A", "B"], "edges": [("A", "B")]}
        results = []
        errors = []

        def worker():
            try:
                for _ in range(5):
                    results.append(engine.generate(spec))
            except Exception as e:
                errors.append(e)

        # Act
        threads = [threading.Thread(target=worker) for _ in range(5)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        # Assert
        assert len(errors) == 0
        assert len(results) == 25
        assert all(isinstance(r, str) for r in results)


